import com.varabyte.kobweb.core.AppGlobals
import com.varabyte.kobweb.navigation.BasePath
import com.varabyte.kobweb.navigation.Router
import com.varabyte.kobweb.navigation.UpdateHistoryMode
import com.varabyte.kobweb.navigation.remove
import com.varabyte.kobweb.silk.defer.DeferringHost
import kotlinx.browser.document
import kotlinx.browser.window
import org.jetbrains.compose.web.renderComposable
import com.probro.khoded.pages.AboutPage as _com_probro_khoded_pages_AboutPage
import com.probro.khoded.pages.ContactPage as _com_probro_khoded_pages_ContactPage
import com.probro.khoded.pages.Index as _com_probro_khoded_pages_Index
import com.probro.khoded.pages.ServicesPage as _com_probro_khoded_pages_ServicesPage

public fun main() {
    AppGlobals.initialize(mapOf("title" to "Khoded | Where your vision takes center stage."))
    BasePath.set("")
    val router = Router()
    com.varabyte.kobweb.core.init.initKobweb(router) { ctx ->
        ctx.router.register(
            "/",
        ) { pageCtx -> 
            _com_probro_khoded_pages_Index()
        }
        ctx.router.register(
            "/about",
        ) { pageCtx -> 
            _com_probro_khoded_pages_AboutPage()
        }
        ctx.router.register(
            "/contact",
        ) { pageCtx -> 
            _com_probro_khoded_pages_ContactPage()
        }
        ctx.router.register(
            "/services",
        ) { pageCtx -> 
            _com_probro_khoded_pages_ServicesPage()
        }

    }
    router.addRouteInterceptor {
        path = path.removeSuffix(".html").removeSuffix(".htm")
    }

    com.varabyte.kobweb.silk.init.additionalSilkInitialization = { ctx ->
        com.varabyte.kobweb.silk.init.initSilkWidgets(ctx)
        com.varabyte.kobweb.silk.init.initSilkWidgetsKobweb(ctx)
        ctx.theme.registerStyle("heading", com.probro.khoded.styles.HeadingStyle)
        ctx.theme.registerStyle("body-text", com.probro.khoded.styles.BodyTextStyle)
        ctx.theme.registerStyle("button-text", com.probro.khoded.styles.ButtonTextStyle)
        ctx.theme.registerStyle("base-image", com.probro.khoded.styles.BaseImageStyle)
        ctx.theme.registerStyle("mobile-first-container", com.probro.khoded.styles.componentStyles.MobileFirstContainerStyle)
        ctx.theme.registerStyle("service-text-variant", com.probro.khoded.styles.pageStyles.ServiceTextVariant)
        ctx.theme.registerStyle("service-description-variant", com.probro.khoded.styles.pageStyles.ServiceDescriptionVariant)
        ctx.theme.registerVariant("-landing", com.probro.khoded.styles.LandingImageVariant
        )
        ctx.theme.registerVariant("-service", com.probro.khoded.styles.ServiceImageVariant
        )
        ctx.theme.registerVariant("-consultation", com.probro.khoded.styles.ConsultationImageVariant
        )
        ctx.theme.registerVariant("-underline", com.probro.khoded.styles.UnderlineImageVariant
        )
        ctx.theme.registerVariant("-navigation", com.probro.khoded.styles.componentStyles.NavigationContainerVariant
        )
        ctx.theme.registerVariant("-enhanced-primary", com.probro.khoded.styles.componentStyles.EnhancedPrimaryButtonVariant
        )
        ctx.theme.registerVariant("-text-backing-card", com.probro.khoded.styles.componentStyles.TextBackingCardVariant
        )
        ctx.theme.registerVariant("-pink-under-line-varaint", com.probro.khoded.styles.pageStyles.PinkUnderLineVaraint
        )
        ctx.theme.registerVariant("-black-underline", com.probro.khoded.styles.pageStyles.BlackUnderlineVariant
        )
        ctx.theme.registerVariant("-plane", com.probro.khoded.styles.pageStyles.PlaneImageVariant
        )
        ctx.theme.registerKeyframes("fade-in", com.probro.khoded.styles.fadeIn)
        ctx.theme.registerKeyframes("slide-in-up", com.probro.khoded.styles.slideInUp)
        ctx.theme.registerKeyframes("slide-in-down", com.probro.khoded.styles.slideInDown)
        ctx.theme.registerKeyframes("slide-in-left", com.probro.khoded.styles.slideInLeft)
        ctx.theme.registerKeyframes("slide-in-right", com.probro.khoded.styles.slideInRight)
        ctx.theme.registerKeyframes("scale-in", com.probro.khoded.styles.scaleIn)
        ctx.theme.registerKeyframes("zoom-in", com.probro.khoded.styles.zoomIn)
        ctx.theme.registerKeyframes("fade-out", com.probro.khoded.styles.fadeOut)
        ctx.theme.registerKeyframes("slide-out-up", com.probro.khoded.styles.slideOutUp)
        ctx.theme.registerKeyframes("slide-out-down", com.probro.khoded.styles.slideOutDown)
        ctx.theme.registerKeyframes("scale-out", com.probro.khoded.styles.scaleOut)
        ctx.theme.registerKeyframes("bounce", com.probro.khoded.styles.bounce)
        ctx.theme.registerKeyframes("shake", com.probro.khoded.styles.shake)
        ctx.theme.registerKeyframes("pulse", com.probro.khoded.styles.pulse)
        ctx.theme.registerKeyframes("wobble", com.probro.khoded.styles.wobble)
        ctx.theme.registerKeyframes("spin", com.probro.khoded.styles.spin)
        ctx.theme.registerKeyframes("spin-reverse", com.probro.khoded.styles.spinReverse)
        ctx.theme.registerKeyframes("loading-dots", com.probro.khoded.styles.loadingDots)
        ctx.theme.registerKeyframes("progress", com.probro.khoded.styles.progress)
        ctx.theme.registerKeyframes("slide-in-right-nav", com.probro.khoded.styles.slideInRightNav)
        ctx.theme.registerKeyframes("slide-out-right", com.probro.khoded.styles.slideOutRight)
        ctx.theme.registerKeyframes("drop-down", com.probro.khoded.styles.dropDown)
        ctx.theme.registerKeyframes("stagger-fade-in", com.probro.khoded.styles.staggerFadeIn)
        ctx.theme.registerKeyframes("make-invisible-key-frames", com.probro.khoded.styles.animations.makeInvisibleKeyFrames)
        ctx.theme.registerKeyframes("make-visible-key-frames", com.probro.khoded.styles.animations.makeVisibleKeyFrames)
        ctx.theme.registerKeyframes("shift-forward-key-frames", com.probro.khoded.styles.animations.shiftForwardKeyFrames)
        ctx.theme.registerKeyframes("shift-backward", com.probro.khoded.styles.animations.shiftBackwardKeyframes)
        ctx.theme.registerKeyframes("job-posting-shift-down-key-frames", com.probro.khoded.styles.animations.jobPostingShiftDownKeyFrames)
        ctx.theme.registerKeyframes("job-posting-shift-up-key-frames", com.probro.khoded.styles.animations.jobPostingShiftUPKeyFrames)
        ctx.theme.registerKeyframes("fall-in", com.probro.khoded.utils.fallInAnimation)
        ctx.theme.registerKeyframes("fly-up", com.probro.khoded.utils.flyUpAnimation)
        com.probro.khoded.initSilk(ctx)
    }

    router.tryRoutingTo(BasePath.remove(window.location.href.removePrefix(window.origin)), UpdateHistoryMode.REPLACE)

    // For SEO, we may bake the contents of a page in at build time. However, we will
    // overwrite them the first time we render this page with their composable, dynamic
    // versions. Think of this as poor man's hydration :)
    // See also: https://en.wikipedia.org/wiki/Hydration_(web_development)
    val root = document.getElementById("_kobweb-root")!!
    while (root.firstChild != null) { root.removeChild(root.firstChild!!) }

    renderComposable(rootElementId = "_kobweb-root") {
        com.probro.khoded.MyApp {
            router.renderActivePage { DeferringHost { it() } }
        }
    }
}
